<?php use SwimlogStandalone\TrainingBalance as TB;use SwimlogStandalone\AnalyticsReports as AR; ?>
<section class="calendar-panel workout-page" aria-labelledby="balance-title"><h2 id="balance-title">Training Balance</h2><p>Recorded swimming distribution, not an ideal training prescription or a fitness/recovery score. Running, walking and measurements are excluded. Stroke, activity and source-distance profiles use different evidence and denominators.</p>
<?php if(is_wp_error($balance)): ?><p role="alert"><?php echo esc_html($balance->get_error_message()); ?></p><p><a href="/?screen=balance">Reset report</a></p><?php else:$m=$balance;$s=$m['summary']; ?>
<form method="get" class="log-filters"><input type="hidden" name="screen" value="balance"><div><label for="balance-months">Period (months)</label><input id="balance-months" name="months" type="number" min="1" max="24" required value="<?php echo esc_attr($m['months']); ?>"></div><button>Apply period</button></form><p><?php echo esc_html('Evidence window: '.$m['window']['current_start'].' through '.$m['window']['end'].' in the WordPress site timezone.'); ?></p>
<?php if(!$s['workout_count']): ?><p role="status">No swimming workouts are recorded in this period.</p><?php endif; ?>
<h3>Pool and open-water balance</h3><p>Distance shares use known workout-summary distances in meters. Sessions without a known distance are counted separately; a missing distance is not proof of zero swimming. Rest is not used to infer intensity or training zones.</p>
<?php $chart=array();foreach(array('pool'=>'Pool','open_water'=>'Open water')as$key=>$label)if($m['coverage'][$key]['known'])$chart[]=array('label'=>$label,'value'=>$s[$key.'_distance_m']);echo TB::chart($chart,'Known swimming distance: pool versus open water'); ?>
<div class="entry-compare"><table><caption>Workout-summary distance and coverage</caption><thead><tr><th scope="col">Activity</th><th scope="col">Sessions</th><th scope="col">Known distance</th><th scope="col">Share of known swim distance</th><th scope="col">Sessions without distance</th></tr></thead><tbody><?php foreach(array('pool'=>'Pool swimming','open_water'=>'Open-water swimming')as$key=>$label):$coverage=$m['coverage'][$key]; ?><tr><th scope="row"><?php echo esc_html($label); ?></th><td><?php echo esc_html($s[$key.'_workouts']); ?></td><td><?php echo esc_html($coverage['known']?AR::distance($s[$key.'_distance_m']):'Unavailable'); ?></td><td><?php echo esc_html($coverage['known']?TB::share($s[$key.'_distance_m'],$s['distance_m']):'Unavailable'); ?></td><td><?php echo esc_html($coverage['missing']); ?></td></tr><?php endforeach; ?></tbody></table></div>
<h3>Pool stroke mix</h3><p>Shares below use qualifying active pool-length distance within each native course, separately from workout totals above. Rest and zero-distance lengths are excluded by the plugin. Unknown stroke remains visible. Summary-only swims and open-water distance cannot supply a pool stroke breakdown.</p>
<?php foreach(array('m'=>'Meter courses','yd'=>'Yard courses')as$unit=>$label):$rows=$m['stroke_volume'][$unit];$total=$m['pool_course'][$unit]['distance_native']; ?><section class="comparison-stroke"><h4><?php echo esc_html($label); ?></h4><?php if(!$rows): ?><p>No qualifying active-length stroke evidence.</p><?php else:$chart=array();foreach($rows as$stroke=>$row)$chart[]=array('label'=>$m['strokes'][$stroke]??'Unknown stroke','value'=>$row['distance_native']);echo TB::chart($chart,'Active pool stroke distance in '.$unit); ?>
<div class="entry-compare"><table><caption><?php echo esc_html('Active-length stroke distribution in '.$unit); ?></caption><thead><tr><th scope="col">Stroke</th><th scope="col">Distance</th><th scope="col">Share</th><th scope="col">Active lengths</th></tr></thead><tbody><?php foreach($rows as$stroke=>$row): ?><tr><th scope="row"><?php echo esc_html($m['strokes'][$stroke]??'Unknown stroke'); ?></th><td><?php echo esc_html(AR::distance($row['distance_native'],$unit)); ?></td><td><?php echo esc_html(TB::share($row['distance_native'],$total)); ?></td><td><?php echo esc_html($row['length_count']); ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><?php endforeach; ?>
<h3>Recorded distance profiles</h3><p>These are descriptive distance bands, not intensity zones. Manual entries count documented repetitions, including untimed ones. Imported entries count positive-distance recorded laps; laps are not confirmed repetitions or continuous bouts. The two sources and their native courses stay separate. Warm-ups, drills and equipment use are not guessed from lap distance.</p>
<?php if(!$m['profiles']): ?><p>No documented repetition or recorded lap-distance breakdown is available.</p><?php endif;foreach($m['profiles']as$profile):$bins=$profile['bins'];$total=array_sum(array_column($bins,'distance'));$labels=array('Up to 100','Over 100 to 400','Over 400');$chart=array();foreach($bins as$i=>$bin)$chart[]=array('label'=>$labels[$i],'value'=>$bin['distance']); ?><section class="comparison-stroke"><h4><?php echo esc_html(($profile['source']==='manual'?'Documented manual repetitions':'Recorded imported laps').' · '.$profile['course']); ?></h4><?php echo TB::chart($chart,'Recorded source-distance bands; exact values below'); ?><div class="entry-compare"><table><caption>Distance shares within this source/course profile</caption><thead><tr><th scope="col">Distance per repetition/lap</th><th scope="col">Count</th><th scope="col">Recorded distance</th><th scope="col">Share</th></tr></thead><tbody><?php foreach($bins as$i=>$bin): ?><tr><th scope="row"><?php echo esc_html($labels[$i].' '.$profile['course']); ?></th><td><?php echo esc_html($bin['count']); ?></td><td><?php echo esc_html(AR::distance($bin['distance'],$profile['course'])); ?></td><td><?php echo esc_html(TB::share($bin['distance'],$total)); ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endforeach; ?>
<p><?php echo esc_html($m['unclassified']); ?> pool sessions have no usable repetition/lap breakdown or native course. Source-distance profiles can differ from workout summaries and active-length totals; they are not silently reconciled or used as complete training-load measures.</p>
<?php endif; ?></section>
